# ─── DISCRETE NLP VECTOR SCALARS ──────────────────────────────────────────────
poultry_keys      = list(POULTRY_KNOWLEDGE.keys())
poultry_questions = [v['question'] for v in POULTRY_KNOWLEDGE.values()]
poultry_vectorizer = TfidfVectorizer(stop_words='english', ngram_range=(1, 2))
poultry_vectors    = poultry_vectorizer.fit_transform(poultry_questions)

crop_keys      = list(CROP_KNOWLEDGE.keys())
crop_questions = [v['question'] for v in CROP_KNOWLEDGE.values()]
crop_vectorizer = TfidfVectorizer(stop_words='english', ngram_range=(1, 2))
crop_vectors    = crop_vectorizer.fit_transform(crop_questions)

# ─── ADVANCED SEMANTIC FOLLOW-UP INTENT VECTORIZER ────────────────────────────
FOLLOWUP_INTENT_EXAMPLES = [
    "how do i treat it", "what is the remedy", "any solution for this", "how to manage it",
    "give me the cure", "how can i fix this", "what should i do now", "preventative measures",
    "stop the disease spreading", "any medicine available", "how to treat the condition", 
    "help me fix this", "how do i handle this", "solve this", "treatment options"
]

# CRITICAL FIX: Explicitly compile vocabulary arrays using .fit_transform()
fallback_followup_vectorizer = TfidfVectorizer(stop_words='english', ngram_range=(1, 2))
fallback_followup_vectors    = fallback_followup_vectorizer.fit_transform(FOLLOWUP_INTENT_EXAMPLES)
# ─── CONTEXT PROCESSING INTERFACE ENGINE ──────────────────────────────────────
def get_chatbot_response(user_query, current_session):
    """
    Evaluates queries across separated vector spaces. Uses an incoming session 
    dictionary argument to maintain state across independent HTTP loops.
    """
    query_clean = user_query.lower().strip()
    
    # 1. Evaluate user string for follow-up intents targeting previous key nodes
    # Check if a valid memory key exists in the persistent session cookie framework
    if current_session.get("last_matched_key") is not None:
        q_intent_vector = fallback_followup_vectorizer.transform([query_clean])
        intent_sims = cosine_similarity(q_intent_vector, fallback_followup_vectors).flatten()
        
        # If the user's sentence hits a baseline semantic match with fixing/handling/remedies...
        if np.max(intent_sims) > 0.15:
            last_key  = current_session["last_matched_key"]
            last_type = current_session["last_matched_type"]
            
            kb_source = POULTRY_KNOWLEDGE if last_type == "poultry" else CROP_KNOWLEDGE
            data = kb_source[last_key]
            
            if "remedy" in data:
                return {
                    "status": "success",
                    "context": "follow_up",
                    "response": data["remedy"],
                    "why": data["why"],
                    "matched_question": f"Follow-up context: {data['question']}"
                }
            else:
                return {
                    "status": "success",
                    "context": "follow_up_fallback",
                    "response": f"For further resolution regarding this topic: {data['why']}",
                    "why": data["why"],
                    "matched_question": f"Follow-up context (General): {data['question']}"
                }

    # 2. Standalone Parallel Query Routing Pipeline (For original questions)
    p_vector = poultry_vectorizer.transform([query_clean])
    p_sims   = cosine_similarity(p_vector, poultry_vectors).flatten()
    best_p_idx = np.argmax(p_sims)
    highest_p_score = p_sims[best_p_idx]

    c_vector = crop_vectorizer.transform([query_clean])
    c_sims   = cosine_similarity(c_vector, crop_vectors).flatten()
    best_c_idx = np.argmax(c_sims)
    highest_c_score = c_sims[best_c_idx]

    if highest_p_score > highest_c_score and highest_p_score > 0.18:
        matched_key = poultry_keys[best_p_idx]
        data = POULTRY_KNOWLEDGE[matched_key]
        
        # Save variables directly to the session object
        current_session["last_matched_key"]  = matched_key
        current_session["last_matched_type"] = "poultry"
        
        return {
            "status": "success",
            "context": "initial_question",
            "response": data["response"],
            "why": data["why"],
            "matched_question": data["question"]
        }
        
    elif highest_c_score >= highest_p_score and highest_c_score > 0.18:
        matched_key = crop_keys[best_c_idx]
        data = CROP_KNOWLEDGE[matched_key]
        
        # Save variables directly to the session object
        current_session["last_matched_key"]  = matched_key
        current_session["last_matched_type"] = "crop"
        
        return {
            "status": "success",
            "context": "initial_question",
            "response": data["response"],
            "why": data["why"],
            "matched_question": data["question"]
        }
    
    else:
        return {
            "status": "fallback",
            "response": "I'm still learning! Ask about fertilizer, pests, diseases, or planting times.",
            "why": "Calculated spatial scores dropped beneath matching threshold barriers."
        }

# ─── DATABASE ─────────────────────────────────────────────────────────────────
def get_db():
    """Return a connection with row_factory set."""
    conn = sqlite3.connect('agri_go.db')
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = sqlite3.connect('agri_go.db')
    cursor = conn.cursor()

    # Core tables
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS produce (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            name        TEXT,
            price       REAL,
            unit        TEXT,
            location    TEXT,
            image_url   TEXT,
            category    TEXT,
            farmer_id   TEXT,
            contact     TEXT,
            quantity    INTEGER DEFAULT 0
        )
    ''')

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            fullname    TEXT,
            telephone   TEXT,
            email       TEXT UNIQUE,
            password    TEXT,
            location    TEXT,
            farm_type   TEXT
        )
    ''')

    cursor.execute('''
        CREATE TABLE IF NOT EXISTS orders (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            produce_id      INTEGER,
            produce_name    TEXT,
            buyer_name      TEXT,
            buyer_contact   TEXT,
            farmer_id       TEXT,
            quantity        INTEGER,
            total_price     REAL,
            delivery_method TEXT,
            status          TEXT DEFAULT 'Pending',
            created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    # Audit log table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS audit_log (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            farmer_id   TEXT    NOT NULL,
            type        TEXT    NOT NULL,
            action      TEXT    NOT NULL,
            details     TEXT,
            timestamp   DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    # SMS log table
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS sms_log (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            farmer_id   TEXT NOT NULL,
            order_id    INTEGER,
            phone       TEXT,
            message     TEXT,
            status      TEXT DEFAULT 'sent',
            sent_at     DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')

    # Triggers — use CREATE TRIGGER IF NOT EXISTS (SQLite 3.30+)
    # Log new order
    cursor.execute('''
        CREATE TRIGGER IF NOT EXISTS log_new_order
        AFTER INSERT ON orders
        BEGIN
            INSERT INTO audit_log (farmer_id, type, action, details)
            VALUES (
                NEW.farmer_id,
                'order',
                'New order received for ' || NEW.produce_name,
                'Buyer: ' || NEW.buyer_name || ' | Qty: ' || CAST(NEW.quantity AS TEXT) || ' | Total: GHC' || CAST(NEW.total_price AS TEXT)
            );
        END
    ''')

    # Log order status change
    cursor.execute('''
        CREATE TRIGGER IF NOT EXISTS log_order_status
        AFTER UPDATE OF status ON orders
        BEGIN
            INSERT INTO audit_log (farmer_id, type, action, details)
            VALUES (
                NEW.farmer_id,
                'order',
                'Order ' || NEW.status || ' for ' || NEW.produce_name,
                'Buyer: ' || NEW.buyer_name || ' | Status: ' || OLD.status || ' -> ' || NEW.status
            );
        END
    ''')

    # Log produce insert
    cursor.execute('''
        CREATE TRIGGER IF NOT EXISTS log_produce_add
        AFTER INSERT ON produce
        BEGIN
            INSERT INTO audit_log (farmer_id, type, action, details)
            VALUES (
                NEW.farmer_id,
                'inventory',
                'Listed new produce: ' || NEW.name,
                'Price: GHC' || CAST(NEW.price AS TEXT) || ' | Qty: ' || CAST(NEW.quantity AS TEXT) || ' | Category: ' || NEW.category
            );
        END
    ''')

    # Log produce delete
    cursor.execute('''
        CREATE TRIGGER IF NOT EXISTS log_produce_delete
        AFTER DELETE ON produce
        BEGIN
            INSERT INTO audit_log (farmer_id, type, action, details)
            VALUES (
                OLD.farmer_id,
                'inventory',
                'Removed produce: ' || OLD.name,
                'Was listed at GHC' || CAST(OLD.price AS TEXT)
            );
        END
    ''')

    # Top produce view
    cursor.execute('''
        CREATE VIEW IF NOT EXISTS top_produce_view AS
        SELECT
            p.name,
            p.farmer_id,
            SUM(o.quantity)    AS units_sold,
            SUM(o.total_price) AS revenue
        FROM orders o
        JOIN produce p ON p.id = o.produce_id
        WHERE o.status = 'Completed'
        GROUP BY p.id, p.name, p.farmer_id
        ORDER BY revenue DESC
    ''')

    conn.commit()
    conn.close()
    print("Database initialized successfully.")

init_db()

# ─── HELPERS ──────────────────────────────────────────────────────────────────
def process_and_predict(model, img_file, classes):
    img       = Image.open(io.BytesIO(img_file.read())).convert('RGB')
    img       = img.resize((224, 224))
    img_array = image.img_to_array(img)
    img_array = np.expand_dims(img_array, axis=0) / 255.0
    preds     = model.predict(img_array)
    idx       = int(np.argmax(preds[0]))
    return classes[idx], float(np.max(preds[0])) * 100

def log_audit(farmer_id, log_type, action, details=''):
    """Manually insert an audit log entry (use alongside triggers for actions
    not covered by DB triggers, e.g. auth events)."""
    try:
        conn   = get_db()
        cursor = conn.cursor()
        cursor.execute(
            'INSERT INTO audit_log (farmer_id, type, action, details) VALUES (?, ?, ?, ?)',
            (farmer_id, log_type, action, details)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"Audit log error: {e}")

