@app.route('/api/update-produce/<int:item_id>', methods=['PATCH'])
def update_produce(item_id):
    try:
        conn   = sqlite3.connect('agri_go.db')
        cursor = conn.cursor()
        fields = ['name','price','unit','quantity','category','contact','location']
        updates, values = [], []
        for f in fields:
            val = request.form.get(f)
            if val is not None:
                updates.append(f'{f} = ?')
                values.append(val)
        if 'image' in request.files:
            file     = request.files['image']
            filename = secure_filename(file.filename)
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            file.save(filepath)
            updates.append('image_url = ?')
            values.append(f'http://localhost:3000/static/uploads/{filename}')

        if not updates:
            conn.close()
            return jsonify({"message": "Nothing to update"}), 400
        values.append(item_id)
        cursor.execute(f"UPDATE produce SET {', '.join(updates)} WHERE id = ?", values)
        conn.commit()
        conn.close()
        return jsonify({"message": "Updated"}), 200
    except Exception as e:
        return jsonify({"message": str(e)}), 500        

@app.route('/api/change-password', methods=['PATCH'])
def change_password():
    data         = request.json
    farmer_id    = data.get('farmer_id', '').strip()
    old_password = data.get('old_password', '')
    new_password = data.get('new_password', '')

    if not farmer_id or not old_password or not new_password:
        return jsonify({"status": "error", "message": "All fields required"}), 400

    try:
        conn   = sqlite3.connect('agri_go.db')
        cursor = conn.cursor()
        cursor.execute(
            'SELECT id FROM users WHERE fullname = ? AND password = ?',
            (farmer_id, old_password)
        )
        user = cursor.fetchone()
        if not user:
            conn.close()
            return jsonify({"status": "error", "message": "Incorrect current password."}), 401

        cursor.execute(
            'UPDATE users SET password = ? WHERE fullname = ?',
            (new_password, farmer_id)
        )
        conn.commit()
        conn.close()
        log_audit(farmer_id, 'auth', 'Password changed', '')
        return jsonify({"status": "success", "message": "Password changed."})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500

