        #     username='YOUR_AT_USERNAME',  # or os.getenv('AT_USERNAME')
        #     api_key='YOUR_AT_API_KEY'     # or os.getenv('AT_API_KEY')
        # )
        # sms = africastalking.SMS
        # response = sms.send(message, [to], sender_id='AgriGo')
        # print("SMS sent:", response)
