# ─── FIXED ORDERS BACKEND ROUTE SECTION ─────────────────────────────────────

@app.route('/api/place-order', methods=['POST'])
def place_order():
    data = request.json
    try:
        conn   = sqlite3.connect('agri_go.db')
        cursor = conn.cursor()

        # Check stock
        cursor.execute('SELECT quantity FROM produce WHERE id = ?', (data['produce_id'],))
        row = cursor.fetchone()
        if not row or row[0] < int(data['quantity']):
            conn.close()
            return jsonify({"error": "Insufficient stock available"}), 400

        cursor.execute('''
            INSERT INTO orders
                (produce_id, produce_name, buyer_name, buyer_contact,
                 farmer_id, quantity, total_price, delivery_method, status)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'Pending')
        ''', (
            data['produce_id'],   data['produce_name'],
            data['buyer_name'],   data['buyer_contact'],
            data['farmer_id'],    data['quantity'],
            data['total_price'],  data['delivery_method'],
        ))

        # Deduct stock
        cursor.execute(
            'UPDATE produce SET quantity = quantity - ? WHERE id = ?',
            (data['quantity'], data['produce_id'])
        )
        conn.commit()
        conn.close()
        return jsonify({"status": "success", "message": "Order placed successfully"}), 201
    except Exception as e:
        return jsonify({"error": str(e)}), 500

