@app.route('/api/cancel-order/<int:order_id>', methods=['PATCH'])
def cancel_order(order_id):
    """Cancel a pending order and restore stock quantity."""
    try:
        conn   = sqlite3.connect('agri_go.db')
        cursor = conn.cursor()

        # Fetch order details before cancelling to restore stock
        cursor.execute(
            'SELECT produce_id, quantity, status FROM orders WHERE id = ?',
            (order_id,)
        )
        order = cursor.fetchone()

        if not order:
            conn.close()
            return jsonify({"error": "Order not found"}), 404

        produce_id  = order[0]
        qty         = order[1]
        cur_status  = order[2]

        if cur_status != 'Pending':
            conn.close()
            return jsonify({"error": "Only pending orders can be cancelled"}), 400

        # Update status
        cursor.execute(
            "UPDATE orders SET status = 'Cancelled' WHERE id = ?",
            (order_id,)
        )

        # Restore stock
        cursor.execute(
            'UPDATE produce SET quantity = quantity + ? WHERE id = ?',
            (qty, produce_id)
        )

        conn.commit()
        conn.close()
        return jsonify({"status": "success", "message": "Order cancelled and stock restored"}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

