@app.route('/api/farmer-stats/<farmer_id>')
def get_farmer_stats(farmer_id):
    try:
        conn   = sqlite3.connect('agri_go.db')
        cursor = conn.cursor()

        cursor.execute(
            'SELECT COUNT(*) FROM produce WHERE farmer_id = ?',
            (farmer_id,)
        )
        inventory_count = cursor.fetchone()[0] or 0

        cursor.execute(
            'SELECT COALESCE(SUM(price * quantity), 0) FROM produce WHERE farmer_id = ?',
            (farmer_id,)
        )
        inventory_value = cursor.fetchone()[0] or 0

        cursor.execute(
            "SELECT COALESCE(SUM(total_price), 0) FROM orders WHERE farmer_id = ? AND status = 'Completed'",
            (farmer_id,)
        )
        total_revenue = cursor.fetchone()[0] or 0

        cursor.execute(
            "SELECT COUNT(*) FROM orders WHERE farmer_id = ? AND status = 'Pending'",
            (farmer_id,)
        )
        pending_orders = cursor.fetchone()[0] or 0

        conn.close()
        return jsonify({
            "inventory_count": inventory_count,
            "inventory_value": round(inventory_value, 2),
            "total_revenue":   round(total_revenue, 2),
            "pending_orders":  pending_orders,
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500

