@app.route('/api/identify-poultry', methods=['POST', 'OPTIONS'])
def identify_poultry():
    # 1. INSTANTLY intercept the browser's preflight check and return an OK status
    if request.method == 'OPTIONS':
        response = make_response()
        response.headers.add("Access-Control-Allow-Origin", "https://agri-go-beta.vercel.app")
        response.headers.add('Access-Control-Allow-Headers', 'Content-Type,Authorization')
        response.headers.add('Access-Control-Allow-Methods', 'POST,OPTIONS')
        return response, 200

    try:
        if not poultry_model:
            return jsonify({"error": "Model missing on server. Check your .h5 file deployment path."}), 503
            
        if 'image' not in request.files:
            return jsonify({"error": "No image file provided in the request"}), 400

        label, conf = process_and_predict(
            poultry_model, request.files['image'], POULTRY_CLASS_NAMES
        )
        
        if label == "Invalid":
            return jsonify({
                "condition": "Invalid Image",
                "confidence": f"{conf:.1f}%",
                "advice": "The image does not appear to be poultry-related. Please upload a clear photo of droppings."
            })
            
        if conf < 65.0:
            return jsonify({
                "condition": "Low Confidence",
                "confidence": f"{conf:.1f}%",
                "advice": "Photo unrecognised or too blurry. Please retake with better lighting."
            })
            
        if label == "Cocci":
            display, advice = "Coccidiosis", (
                "Coccidiosis symptoms detected. Isolate birds immediately and "
                "contact a veterinarian for Amprolium treatment."
            )
        else:
            display, advice = "Healthy", (
                "Your birds appear healthy. Maintain dry litter and clean water to prevent outbreaks."
            )
            
        return jsonify({"condition": display, "confidence": f"{conf:.1f}%", "advice": advice})

    except Exception as e:
        print(f"POULTRY DIAGNOSTICS RUNTIME EXCEPTION: {str(e)}")
        return jsonify({"error": "Internal AI processing error", "details": str(e)}), 500


