# ─── CHATBOT ──────────────────────────────────────────────────────────────────
# Definitive domain-isolation key mappings to prevent vector contamination
POULTRY_KEYWORDS = ["poultry", "chicken", "bird", "chick", "layer", "broiler", "coccidiosis", "newcastle", "gumboro", "pox", "egg", "beak", "flock", "litter", "shavings"]
CROP_KEYWORDS    = ["crop", "maize", "corn", "tomato", "cassava", "cocoa", "onion", "pepper", "cabbage", "cucumber", "blight", "streak", "mosaic", "wilt", "pod", "fertilizer", "npk", "urea", "soil", "pesticide", "seedling", "funnel", "armyworm"]

@app.route('/api/chat', methods=['POST'])
def chat():
    data       = request.json
    user_input = data.get('message', '').lower().strip()
    last_topic = data.get('last_topic') 

    # ─── 1. POLITE SMALL-TALK PRESETS ─────────────────────────────────────────
    polite = ["thank you", "thanks", "okay", "ok", "alright", "cool", "noted"]
    if any(user_input == w or user_input.startswith(w + " ") for w in polite):
        return jsonify({
            "response": "You're welcome! Feel free to ask more.", 
            "intent": "polite"
        })

    # ─── 2. CONTEXTUAL FOLLOW-UP ANALYSIS (REMEDIES / TREATMENT) ──────────────
    if last_topic:
        if last_topic in poultry_keys:
            data_node = POULTRY_KNOWLEDGE.get(last_topic)
            current_type = "poultry"
        else:
            data_node = CROP_KNOWLEDGE.get(last_topic)
            current_type = "crop"

        if data_node:
            if user_input in ("why", "why?", "tell me more"):
                return jsonify({
                    "response": f"Deep Dive Context:\n{data_node['why']}",
                    "intent": last_topic
                })

            q_intent_vector = fallback_followup_vectorizer.transform([user_input])
            intent_sims     = cosine_similarity(q_intent_vector, fallback_followup_vectors).flatten()
            
            if np.max(intent_sims) > 0.20:
                if "remedy" in data_node:
                    return jsonify({
                        "response": data_node["remedy"],
                        "intent": last_topic
                    })
                else:
                    return jsonify({
                        "response": f"Operational Guidance:\n{data_node['why']}",
                        "intent": last_topic
                    })

    # ─── 3. KEYWORD GUARD LAYER (HARD DOMAIN ISOLATION) ──────────────────────
    # Force direct dictionary selection if definitive category tokens are flagged
    has_poultry_keyword = any(kw in user_input for kw in POULTRY_KEYWORDS)
    has_crop_keyword    = any(kw in user_input for kw in CROP_KEYWORDS)

    # ─── 4. SEMANTIC INFERENCE SEARCH PIPELINE ─────────────────────────────────
    try:
        highest_p_score = -1.0
        highest_c_score = -1.0
        best_p_idx = 0
        best_c_idx = 0

        # Run poultry vector processing ONLY if not strictly a crop query
        if has_poultry_keyword or not has_crop_keyword:
            p_vector = poultry_vectorizer.transform([user_input])
            p_sims   = cosine_similarity(p_vector, poultry_vectors).flatten()
            best_p_idx = np.argmax(p_sims)
            highest_p_score = p_sims[best_p_idx]

        # Run crop vector processing ONLY if not strictly a poultry query
        if has_crop_keyword or not has_poultry_keyword:
            c_vector = crop_vectorizer.transform([user_input])
            c_sims   = cosine_similarity(c_vector, crop_vectors).flatten()
            best_c_idx = np.argmax(c_sims)
            highest_c_score = c_sims[best_c_idx]

        # Route dynamically based on bounded calculations
        if highest_p_score > highest_c_score and highest_p_score > 0.15:
            intent = poultry_keys[best_p_idx]
            return jsonify({
                "response": POULTRY_KNOWLEDGE[intent]['response'], 
                "intent": intent
            })
            
        elif highest_c_score >= highest_p_score and highest_c_score > 0.15:
            intent = crop_keys[best_c_idx]
            return jsonify({
                "response": CROP_KNOWLEDGE[intent]['response'], 
                "intent": intent
            })

    except Exception as e:
        print(f"NLP Matching Interface Exception: {e}")

    # ─── 5. FALLBACK TERMINAL ─────────────────────────────────────────────────
    return jsonify({
        "response": "I didn't quite catch that specific condition. Could you rephrase your question?",
        "intent": "unknown"
    })

